import JSON

"""
	gen( mu, sigma, name )

Generate fixture data and write to file.

The excess kurtosis is evaluated in extended precision from the textbook formula `exp(4*sigma^2) + 2*exp(3*sigma^2) + 3*exp(2*sigma^2) - 6`, which cancels in double precision for small `sigma`.

# Arguments

* `mu`: location parameter
* `sigma`: scale parameter
* `name::AbstractString`: output filename

# Examples

``` julia
julia> mu = rand( 1000 ) .* -10.0;
julia> sigma = rand( 1000 ) .* 5.0;
julia> gen( mu, sigma, "data.json" );
```
"""
function gen( mu, sigma, name )
	z = setprecision( BigFloat, 2048 ) do
		s2 = BigFloat.( sigma ) .^ 2;
		Float64.( exp.( 4 .* s2 ) .+ ( 2 .* exp.( 3 .* s2 ) ) .+ ( 3 .* exp.( 2 .* s2 ) ) .- 6 )
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("mu", mu),
		("sigma", sigma),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Generate fixtures:
mu = rand( 100 ) .* 2.0 .- 4.0;
sigma = rand( 100 ) .* 5.0;
gen( mu, sigma, "data.json" );

# Small `sigma` (above `1e-154`, where `sigma^2` underflows):
mu = ( rand( 1000 ) .* 4.0 ) .- 2.0;
sigma = exp10.( range( -150.0, stop = -1.0, length = 1000 ) );
gen( mu, sigma, "small_sigma.json" );
